import {MONTHS,SEGMENTS,COVERAGES,REGIONS,ASSUMPTIONS,scenario,teams,reference,spend,validate,rank,simulate} from './engine.js';
const $=s=>document.querySelector(s), fmt=(n,d=0)=>Number(n).toLocaleString('tr-TR',{maximumFractionDigits:d,minimumFractionDigits:d}),money=n=>Math.abs(n)>=1e6?`₺${fmt(n/1e6,1)} mn`:`₺${fmt(n)}`,pct=n=>`%${fmt(n*100,1)}`,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='risk-arena-session-v1';const fresh=()=>({schema:1,teams:teams(),config:scenario(),view:'studio',team:0,step:0,phase:'decisions',deadline:Date.now()+25*60000,month:-1,results:[],running:false,metric:'score',focusTeam:0,detail:false,sound:false,reduce:false,finalReveal:false});let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.schema!==1)state=fresh();}catch{state=fresh();}state.running=false;state.finalReveal=false;let timer,transitionTimer,countdownTimer,countdown=null,modal=null,lastLeader=null,leaderFlash=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-state')&&( $('#save-state').textContent='Taslak kaydedildi');}catch{$('#save-state')&&($('#save-state').textContent='Depolama dolu · oturum kaydedilemedi');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
const icon=(name,size=20)=>{const p={grid:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h6v6h-6z',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',sliders:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',chart:'M4 3v17h17 M7 14l4-5 4 3 5-8',cup:'M8 3h8v8a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 15v5 M8 21h8',arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'M9 5l7 7-7 7',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',play:'m8 4 12 8-12 8z',pause:'M8 5v14 M16 5v14',expand:'M9 3H3v6 M15 3h6v6 M3 15v6h6 M21 15v6h-6',info:'M12 11v6 M12 7v1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',reset:'M3 11a9 9 0 1 1 2 7 M3 4v7h7',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a7 7 0 0 1 14 0v3 M16 4a4 4 0 0 1 0 8 M18 15a5 5 0 0 1 4 5',bolt:'m13 2-9 12h7l-1 8 10-12h-7z',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z',volume:'M3 9h4l5-5v16l-5-5H3z M16 8a6 6 0 0 1 0 8',x:'m6 6 12 12 M6 18 18 6',file:'M6 2h8l4 4v16H6z M14 2v5h4 M9 12h6 M9 16h6'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(p[name]||p.grid).split(' M').map((v,i)=>`<path d="${i?'M':''}${v}"/>`).join('')}</svg>`;};
function emblem(t,large=false){const shapes=['<path d="M6 28 18 5l12 23h-8l-4-9-4 9z"/>','<path d="m18 3 4 11 11 4-11 4-4 11-4-11-11-4 11-4z"/>','<path d="m18 3 4 10 11 1-8 7 3 11-10-6-10 6 3-11-8-7 11-1z"/>','<path d="m18 3 13 5v10c0 8-13 15-13 15S5 26 5 18V8z"/>','<path d="M3 12q7-8 15 0t15 0v6q-7 8-15 0T3 18z M3 23q7-8 15 0t15 0v6q-7 8-15 0T3 29z"/>','<path d="m2 29 11-22 7 12 5-8 10 18H23l-3-6-3 6z"/>'];return `<span class="emblem ${large?'large':''}" style="--team:${t.color}"><svg viewBox="0 0 36 36" aria-hidden="true">${shapes[t.emblem]}</svg></span>`;}
const t=()=>state.teams.find(x=>x.id===state.team), s=()=>t().strategy, current=()=>state.results[state.month], active=()=>state.phase==='simulation'||state.phase==='complete';
function button(label,action,cls='secondary',attrs=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;}
const status=t=>!t.connected?'Bağlantı kesildi':t.locked?'Teslim edildi':t.revision?'Revizyona açıldı':validate(t,state.config).length?'Eksik karar':'Taslak';
function nav(label,view,ic){return `<button data-view="${view}" class="nav-item ${state.view===view?'active':''}">${icon(ic)}<span>${label}</span>${state.view===view?'<i></i>':''}</button>`;}
function shell(content){const role=state.view==='moderator'?'moderator':state.view==='stage'?'stage':'team';return `<div class="app-shell ${role==='stage'?'stage-shell':''}"><aside class="sidebar"><a class="brand" href="#" data-view="lobby"><span class="brand-symbol">${icon('bolt',24)}</span><span>RİSK<span class="brand-light">ARENASI</span></span></a><div class="season"><span class="live-dot"></span> TÜRKİYE ${state.config.year}<small>${esc(state.config.branch)} strateji simülasyonu</small></div><div class="sidebar-label">WORKSHOP ALANI</div><nav>${nav('Oturum lobisi','lobby','grid')}${nav('Pazar dosyası','briefing','book')}${nav('Strateji stüdyosu','studio','sliders')}${nav('Karar teslimi','submit','lock')}<div class="nav-divider"></div>${nav('Takım performansı','performance','chart')}${nav('Final & değerlendirme','final','cup')}</nav><div class="sidebar-bottom"><div class="session-code"><span>OTURUM KODU</span><button data-action="copy-code" title="Oturum kodunu kopyala">RA–2023 ${icon('file',16)}</button></div><p>6 takım. Tek pazar. 12 ay.</p><div class="demo-label">DEMO SENARYOSU</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs">Workshop <span>/</span> ${role==='moderator'?'Moderatör':role==='stage'?'Canlı yayın':'Takım alanı'}</div><div class="role-switch" aria-label="Görünüm seçimi">${[['team','studio','Takım alanı'],['moderator','moderator','Kontrol odası'],['stage','stage','Sahne ekranı']].map(([r,v,l])=>`<button data-view="${v}" class="${role===r?'selected':''}">${l}</button>`).join('')}</div><button class="avatar" data-action="team-picker" aria-label="Demo takımını seç">${esc(t().code.slice(0,2))}</button></header>${content}<footer class="app-footer"><span><span class="connection-dot ${navigator.onLine?'':'offline'}"></span><span id="network-status">${navigator.onLine?'Yerel oturum açık':'Bağlantı kesildi · yerel taslak korunuyor'}</span></span><span>Demo katılımı · eşzamanlı bağlantı yok</span><button data-action="notes">Model hakkında ${icon('info',14)}</button></footer></div></div>`;}
function pageHead(kicker,title,desc,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;}
function teamSelect(){return `<label class="team-picker">Demo takımı <select data-state="team" aria-label="Demo takımı">${state.teams.map(x=>`<option value="${x.id}" ${x.id===state.team?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`;}
function timeLeft(){return Math.max(0,Math.ceil((state.deadline-Date.now())/1000));}function clockText(){const n=timeLeft();return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function field(label,input,help=''){return `<label class="field"><span>${label}</span>${input}${help?`<small>${help}</small>`:''}</label>`;}
function textInput(key,value,placeholder='',max=65){return `<input data-field="${key}" value="${esc(value)}" placeholder="${placeholder}" maxlength="${max}" ${t().locked||active()?'disabled':''}>`;}
function selectInput(key,options,value){return `<select data-field="${key}" ${t().locked||active()?'disabled':''}>${options.map(x=>`<option value="${x.id}" ${String(value)===String(x.id)?'selected':''}>${x.name}</option>`).join('')}</select>`;}
function help(text){return `<details class="help"><summary>${icon('info',15)} Bu karar neyi etkiler?</summary><p>${text}</p></details>`;}
function choices(key,options){return `<div class="choice-row">${options.map(x=>`<button class="choice ${String(s()[key])===String(x.id)?'chosen':''}" data-choice="${key}" data-value="${x.id}" ${t().locked||active()?'disabled':''}>${x.name}${String(s()[key])===String(x.id)?icon('check',15):''}</button>`).join('')}</div>`;}
function range(key,label,min,max,step,unit,description){return `<div class="range-field"><div class="range-title"><label for="${key}">${label}</label><span><input id="${key}" type="number" data-field="${key}" value="${s()[key]}" min="${min}" max="${max}" step="${step}" ${t().locked||active()?'disabled':''}> ${unit}</span></div><input aria-label="${label} kaydırıcı" type="range" data-field="${key}" min="${min}" max="${max}" step="${step}" value="${s()[key]}" ${t().locked||active()?'disabled':''}><div class="range-labels"><span>${fmt(min)} ${unit}</span><span>${fmt(max)} ${unit}</span></div><p>${description}</p></div>`;}
function mix(key,labels){const total=s()[key].reduce((a,b)=>a+b,0);return `<div class="mix-fields">${labels.map((l,i)=>field(l,`<div class="number-wrap"><input aria-label="${l}" type="number" data-mix="${key}" data-index="${i}" min="0" max="100" step="1" value="${s()[key][i]}" ${t().locked||active()?'disabled':''}><span>%</span></div>`)).join('')}</div><p class="mix-total ${total!==100?'error-text':''}" id="${key}-total">Toplam %${fmt(total)} / %100 ${total===100?'✓':'· Dağılımı %100’e tamamlayın.'}</p>`;}
function studioStep(){switch(state.step){case 0:return `<div class="section-title"><span class="step-num">01</span><div><h2>Ürününün temelini at.</h2><p>Şirketini tanımla, müşterine vereceğin güvenceyi seç.</p></div></div><div class="form-pair">${field('Şirket adı',textInput('name',t().name,'Şirketiniz',24))}${field('Ürün adı',textInput('product',s().product,'Ürün adı',40))}</div>${field('Stratejin bir cümlede',textInput('sentence',s().sentence,'Nasıl fark yaratacaksınız?',120),'En fazla 120 karakter. Finalde kararlarınla birlikte gösterilir.')}<div class="field-heading"><h3>Teminat paketi</h3><span>Bir paket seç</span></div><div class="coverage-grid">${COVERAGES.map((c,i)=>`<button data-choice="coverage" data-value="${c.id}" class="coverage ${s().coverage===c.id?'chosen':''}" ${t().locked||active()?'disabled':''}><div class="coverage-top">${icon('shield',25)}<span class="radio-circle">${s().coverage===c.id?icon('check',12):''}</span></div><strong>${c.name}</strong><p>${c.description}</p><span class="coverage-price">${money(SEGMENTS.find(x=>x.id===s().primary).base*c.factor)}<small>referans yıllık prim</small></span></button>`).join('')}</div>${help('Kapsam genişledikçe ürünün çekiciliği ve hasar maliyeti birlikte artar. Her paket için referans prim farklıdır. Fiyat endeksi seçtiğin paketin referansına uygulanır.')}<div class="field-heading"><h3>Muafiyet</h3><span>Her hasarda müşterinin payı</span></div>${choices('deductible',[{id:0,name:'Muafiyetsiz'},{id:5000,name:'₺5.000 / hasar'},{id:10000,name:'₺10.000 / hasar'}])}${help('Muafiyet müşteri tarafından karşılanan hasar tutarıdır. Demo modelinde şirketin hasar yükünü ve müşteri tercih olasılığını azaltır. Poliçe başına değil, her hasar için uygulanır.')}`;
case 1:return `<div class="section-title"><span class="step-num">02</span><div><h2>Doğru müşteri. Doğru fiyat.</h2><p>Herkese ulaşmak ile doğru riski almak arasındaki denge.</p></div></div><div class="form-pair">${field('Ana müşteri segmenti',selectInput('primary',SEGMENTS,s().primary),'Talep uyumu en yüksek hedef.')}${field('İkincil müşteri segmenti',selectInput('secondary',SEGMENTS,s().secondary),'Ana segmentten farklı olmalı.')}</div>${help('Hedefler niyetini gösterir. Gerçekleşen müşteri dağılımı ortak pazardaki fiyat, ürün ve rakip tercihlerinden oluşur.')} ${field('Bölgesel odak',selectInput('region',REGIONS,s().region),'Marmara: yüksek erişim ve risk · İç Anadolu: daha dar erişim ve düşük risk.')}${range('price','Fiyat endeksi',80,120,1,'endeks','100 = seçilen ana segment ve teminat paketinin yıllık referans primi.')}<div class="reference-note" id="price-reference">Referans: ${money(reference(s()))} / yıl → <strong>Teklifin: ${money(reference(s())*s().price/100)} / yıl</strong></div>${help('Düşük fiyat dönüşümü artırırken poliçe başına primi azaltır. Rakipler ve satın almama seçeneğiyle birlikte toplam satış hacmini de etkiler.')}<div class="field-heading"><h3>Risk kabul politikası</h3></div>${choices('risk',[{id:'selective',name:'Seçici kabul'},{id:'balanced',name:'Dengeli kabul'},{id:'broad',name:'Geniş kabul'}])}${help('Seçici kabul daha az müşteriyi kabul eder, hasar riskini azaltır. Geniş kabul hacmi ve risk maruziyetini artırır.')}`;
case 2:return `<div class="section-title"><span class="step-num">03</span><div><h2>Büyümenin yolunu seç.</h2><p>Aynı müşteriler için yarışıyorsunuz. Nerede görünür olacaksın?</p></div></div>${range('marketing','Pazarlama bütçesi',0,state.config.assumptions.budget.value,100000,'TL','Karar bütçesinden bir kez düşülür. Harcama arttıkça ek erişim getirisi azalır.')}<div class="field-heading"><h3>Pazarlama dağılımı</h3><span>Toplam %100</span></div>${mix('marketingMix',['Dijital performans','Marka','İş ortaklıkları'])}${help('Dijital performans şehirli sürücüleri, marka premium müşterileri, iş ortaklıkları aileleri daha güçlü etkiler.')}<div class="field-heading"><h3>Satış kanalı hedefi</h3><span>Toplam %100</span></div>${mix('channels',['Direkt dijital','Acente','Broker'])}${help('Hedef kanal karışımı satış kapasitesini ve edinim maliyetini değiştirir. Gerçekleşen kanal dağılımı kanal çekiciliğiyle hesaplanır. Baz maliyetler dijital %4,5, acente %12, broker %16 primdir.')}<div class="field-heading"><h3>Kanal teşviki</h3></div>${choices('commission',[{id:.8,name:'Ekonomik · ×0,8'},{id:1,name:'Standart · ×1,0'},{id:1.2,name:'Güçlü · ×1,2'}])}${help('Acente ve broker komisyonları seçilen katsayıyla çarpılır. Güçlü teşvik talebi artırır. Komisyon gerçekleşen primden hesaplanır; başlangıç karar bütçesine dahil değildir.')}`;
case 3:return `<div class="section-title"><span class="step-num">04</span><div><h2>Sözünü tutacak gücü kur.</h2><p>Satıştan sonra başlayan deneyim, şirketinin ikinci sınavı.</p></div></div>${range('service','Hasar hizmeti yatırımı',0,state.config.assumptions.budget.value,100000,'TL','Başlangıçta bir kez giderleşir. Hizmet kapasitesini azalan marjinal faydayla artırır.')}<div class="service-visual">${icon('shield',42)}<div><h3>Hizmet bir kapasite kararıdır.</h3><p>Yatırım, büyüyen portföyün hizmet yükünü karşılamanı sağlar. Kullanılmayan kapasite de bir maliyettir.</p></div></div>${help('Kapasite = 3.500 + √(hizmet yatırımı / 1 mn TL) × 6.500 poliçe. Portföy kapasiteyi aşarsa hizmet skoru düşer. Kesin sonuç tüm şirketlerin kararlarından sonra hesaplanır.')}<details class="advanced"><summary>İleri seviye: reasürans ${icon('chevron',18)}</summary><label class="check-label"><input type="checkbox" data-field="reinsurance" ${s().reinsurance?'checked':''} ${t().locked||active()?'disabled':''}> %15 kotpar reasürans</label><p>Brüt primin %15’i devredilir, gerçekleşen hasarın %15’i geri kazanılır. Komisyon iadesi yoktur. Net prim ve net hasara bir kez uygulanır.</p></details><div class="notice">${icon('info')}<p>Sabit operasyon gideri ${money(state.config.assumptions.baseExpense.value)} / ay. Bu gider simülasyon boyunca teknik sonuçtan düşülür.</p></div>`;}}
function summary(){const st=s(),cv=COVERAGES.find(x=>x.id===st.coverage);return `<div class="policy-top"><span>ÜRÜNÜN / CANLI ÖZET</span>${icon('bolt',18)}</div><div class="policy-identity">${emblem(t(),true)}<span>${esc(t().name)}<small>${esc(state.config.branch)} sigortası</small></span></div><h2>${esc(st.product||'Ürününün adı')}</h2><p class="policy-sentence">“${esc(st.sentence||'Stratejini tanımla.')}”</p><div class="policy-price"><small>YILLIK ÖRNEK PRİM</small><strong>${money(reference(st)*st.price/100)}</strong><span>${st.price<100?'Referansın %'+(100-st.price)+' altında':st.price>100?'Referansın %'+(st.price-100)+' üzerinde':'Referans fiyat seviyesinde'}</span></div><dl><div><dt>Hedef müşteri</dt><dd>${SEGMENTS.find(x=>x.id===st.primary).name}</dd></div><div><dt>Teminat</dt><dd>${cv.name}</dd></div><div><dt>Ana kanal hedefi</dt><dd>${['Direkt dijital','Acente','Broker'][st.channels.indexOf(Math.max(...st.channels))]} · %${Math.max(...st.channels)}</dd></div><div><dt>Risk yaklaşımı</dt><dd>${st.risk==='selective'?'Seçici':st.risk==='broad'?'Geniş':'Dengeli'} kabul</dd></div></dl><div class="policy-foot">${icon('info',15)} Bu bir strateji özeti; sonuç tahmini değildir.</div>`;}
function budget(){const total=state.config.assumptions.budget.value,used=spend(s()),left=total-used;return `<div class="budget-heading"><span>Karar bütçesi</span><strong>${money(total)}</strong></div><div class="budget-track"><i style="width:${Math.min(100,s().marketing/total*100)}%;background:var(--blue)"></i><i style="width:${Math.min(100,s().service/total*100)}%;background:var(--purple)"></i></div><div class="budget-line"><span><i style="background:var(--blue)"></i>Pazarlama</span><b>${money(s().marketing)}</b></div><div class="budget-line"><span><i style="background:var(--purple)"></i>Hizmet yatırımı</span><b>${money(s().service)}</b></div><div class="budget-left ${left<0?'error-text':''}"><span>${left<0?'Bütçe aşımı':'Kalan bütçe'}</span><strong>${money(Math.abs(left))}</strong></div><small>${left<0?'Teslim için harcamanı azalt.':'Komisyon ve aylık giderler simülasyonda hesaplanır.'}</small>`;}
function studio(){return `<main class="page studio-page">${pageHead('STRATEJİ STÜDYOSU','Bugünün kararları.<br>Yarının lideri.','Pazar payını büyütürken kârlı kalabilir misin?',`<div class="studio-head-actions">${button(icon('book',17)+' Pazar dosyası','brief-modal','quiet')}<div class="timer">${icon('clock',19)}<div><small>KARAR İÇİN KALAN</small><b id="countdown-clock">${active()?'Kilitlendi':clockText()}</b></div></div></div>`)}<div class="team-context">${emblem(t())}<strong>${esc(t().name)} Sigorta</strong><span class="status-chip ${t().locked?'success':''}">${status(t())}</span><span class="autosave" id="save-state">${icon('check',14)} Taslak kaydedildi</span>${teamSelect()}</div>${t().locked?`<div class="notice success">${icon('lock')}<p>Stratejin kilitlendi. Değişiklik için moderatörün revizyon açması gerekiyor.</p></div>`:''}${timeLeft()===0&&!active()?'<div class="notice warning">Karar süresi doldu. Moderatör süreyi uzatabilir veya geçerli varsayılan stratejiyi uygulayabilir.</div>':''}<div class="studio-layout"><section class="studio-form"><div class="stepper">${['Ürün','Müşteri ve Fiyat','Büyüme','Operasyon'].map((l,i)=>`<button data-step="${i}" class="${state.step===i?'active':state.step>i?'done':''}"><span>${state.step>i?icon('check',13):i+1}</span>${l}</button>`).join('')}</div><div class="form-body">${studioStep()}</div><div class="form-bottom"><span>${state.step+1} / 4 adım</span><div>${state.step>0?button('Geri','prev-step','quiet'):''}${button(state.step<3?'Sonraki adım '+icon('arrow',17):'Kararları gözden geçir '+icon('arrow',17),'next-step','primary')}</div></div></section><aside class="strategy-aside"><section class="policy" id="live-summary" style="--team:${t().color}">${summary()}</section><section class="budget" id="live-budget">${budget()}</section><div class="fair-note">${icon('users',17)} Herkes aynı koşullarda başlar.</div></aside></div></main>`;}
function lobby(){return `<main class="page lobby-page">${pageHead('TÜRKİYE '+state.config.year+' — '+esc(state.config.branch.toLocaleUpperCase('tr-TR')),'6 takım.<br>Tek pazar. <span class="blue-text">12 ay.</span>','Şirketini kur. Stratejini seç. Rekabetin içinde yerini al.',`<div class="lobby-code"><small>OTURUM KODU</small><strong>RA–2023</strong><span>Demo senaryosu</span></div>`)}<div class="lobby-meta"><h2>Oyuncular hazır. Peki ya stratejin?</h2><span>${state.teams.filter(x=>x.locked).length}/6 takım hazır</span></div><div class="team-grid">${state.teams.map(x=>`<button class="team-card" data-select-team="${x.id}" style="--team:${x.color}">${emblem(x,true)}<span class="team-code">${x.code}</span><h3>${esc(x.name)}</h3><p>${esc(x.strategy.sentence)}</p><span class="team-card-status">${icon(x.locked?'check':'sliders',15)} ${status(x)}</span></button>`).join('')}</div><div class="lobby-bottom"><p>Herkes aynı sermaye, aynı bütçe ve aynı müşteri havuzuyla başlar.<br><small>Katılım durumları bu cihazdaki demoya aittir.</small></p><div>${button('Demo takımlarını doldur','load-demo')}${button('Brifingi başlat '+icon('arrow',18),'start-brief','primary')}</div></div></main>`;}
function briefingContent(){const a=state.config.assumptions;return `<div class="brief-stats"><div><span>Başlangıç sermayesi</span><strong>${money(a.capital.value)}</strong><small>Her takım için eşit özkaynak</small></div><div><span>Karar bütçesi</span><strong>${money(a.budget.value)}</strong><small>Pazarlama + hizmet yatırımı</small></div><div><span>Ortak müşteri havuzu</span><strong>${fmt(a.pool.value)}<em>/ ay</em></strong><small>Satın almayan müşteriler dahil</small></div></div><h2>Müşterini tanı.</h2><div class="segment-list">${SEGMENTS.map((g,i)=>`<div><span class="segment-index">${['%44','%36','%20'][i]}</span><div><h3>${g.name}</h3><p>${g.description}</p></div><strong>${money(g.base)}<small>dengeli paket referansı</small></strong></div>`).join('')}</div><div class="brief-columns"><section><h3>Pazarın oyun alanı</h3><p>Marmara: yüksek erişim, yüksek hasar maruziyeti. Ege ve Akdeniz: dengeli profil. İç Anadolu: daha sınırlı erişim ve daha düşük risk.</p><p>Direkt dijital edinim gideri %4,5; acente %12; broker %16. Kanal teşviki acente ve broker maliyetlerini çarpar.</p><p>Baz hasar maliyeti beklentisi aylık ${pct(a.inflation.value)}. Yıl içinde açıklanacak olaylar, ilgili aya kadar takımlara gösterilmez.</p></section><section><h3>Puan nasıl hesaplanır?</h3>${state.config.weights.map((w,i)=>`<div class="weight-line"><span>${['Kârlılık','Prim bazlı pazar payı','Müşteri deneyimi'][i]}</span><b>%${w}</b></div>`).join('')}<p>Kârlılık: kâr / sermaye ${pct(a.profitFloor.value)} → 0; ${pct(a.profitTarget.value)} → 100 puan. Pazar payı: %0 → 0; ${pct(a.shareTarget.value)} → 100 puan. Hizmet: 0 → 0; ${fmt(a.serviceTarget.value)} → 100 puan. Ara değerler doğrusal; puanlar 0–100 sınırında.</p></section></div><details class="brief-rules"><summary>Teslim, sermaye ve eşitlik kuralları</summary><p>Fiyat endeksi 80–120. Her iki dağılım %100 olmalı. Pazarlama ve hizmet yatırımı toplamı karar bütçesini aşamaz. Referans fiyat ana segment ve kapsama göre değişir. Hedef dağılımlar garanti değildir.</p><p>Karar süresi ${state.config.minutes} dakika. Süre bitiminde yalnızca geçerli kilitli kararlar kullanılır. Eksik takımlarda moderatör süre uzatır veya ilan edilen demo stratejisini uygular.</p><p>Özkaynağı herhangi bir ay negatif olan takım ana şampiyonluğa uygun değildir. Eşit puanda teknik kâr, sonra prim bazlı pazar payı belirleyicidir. Tam eşitlikte derece paylaşılır.</p><p>Rozetler: en yüksek prim payı Pazar Lideri; en yüksek teknik kâr Kârlılık Ustası; en yüksek hizmet skoru Müşteri Şampiyonu; ilk aya göre en fazla sıra kazanan En Güçlü Geri Dönüş. Rozetler puanı değiştirmez.</p></details><div class="notice">${icon('info')}<p><strong>Demo senaryosu.</strong> Tüm sayılar ve olaylar eğitim amaçlı varsayımdır; tarihsel 2023 verisi değildir. Pazar payı yalnızca simülasyon pazarını gösterir.</p></div>`;}
function briefing(){return `<main class="page">${pageHead('PAZAR DOSYASI','Herkes aynı koşullarda başlar.','Oyuna girmeden önce fırsatları, kaynakları ve kuralları tanı.')}<div class="white-panel">${briefingContent()}</div><div class="page-actions">${button('Stratejini oluştur '+icon('arrow',18),'go-studio','primary')}</div></main>`;}
function reviewTable(team=t()){const st=team.strategy;return `<dl class="review-list">${[['Şirket / ürün',esc(team.name)+' / '+esc(st.product)],['Strateji',esc(st.sentence)],['Hedef segmentler',SEGMENTS.find(x=>x.id===st.primary).name+' / '+SEGMENTS.find(x=>x.id===st.secondary).name],['Bölge',REGIONS.find(x=>x.id===st.region).name],['Fiyat',st.price+' endeks · '+money(reference(st)*st.price/100)+' / yıl'],['Teminat / muafiyet',COVERAGES.find(x=>x.id===st.coverage).name+' / '+money(st.deductible)+' her hasarda'],['Risk kabulü',st.risk==='selective'?'Seçici':st.risk==='broad'?'Geniş':'Dengeli'],['Pazarlama',money(st.marketing)+' · dijital / marka / ortaklık: '+st.marketingMix.map(x=>'%'+x).join(' / ')],['Kanal hedefi','Dijital / acente / broker: '+st.channels.map(x=>'%'+x).join(' / ')],['Komisyon teşviki','×'+fmt(st.commission,1)],['Hizmet yatırımı',money(st.service)],['Reasürans',st.reinsurance?'%15 kotpar':'Yok']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`;}
function submit(){const errors=validate(t(),state.config);return `<main class="page">${pageHead('KARAR TESLİMİ',t().locked?'Stratejin oyuna hazır.':'Son kontrol. Büyük karar.','Kaptan olarak stratejiyi kilitlemeden önce kararlarını gözden geçir.',teamSelect())}<div class="submit-layout"><section class="white-panel">${t().locked?`<div class="locked-stamp">${icon('lock',36)}<div><h2>Teslim edildi</h2><p>${esc(t().name)} · strateji kilitlendi</p></div></div>`:`<h2>${esc(t().name)} — ${esc(s().product)}</h2>`}${reviewTable()}</section><aside><section class="budget">${budget()}</section><section class="white-panel submit-check"><h3>Teslim kontrolü</h3>${errors.length?`<ul class="error-list">${errors.map(x=>`<li>${x}</li>`).join('')}</ul>`:`<p class="success-text">${icon('check',18)} Bütün kararlar geçerli.</p>`}<p>Kararlar kilitlendikten sonra yalnızca moderatör revizyon açabilir.</p>${button(icon('lock',17)+' '+(t().locked?'Strateji kilitlendi':'Stratejiyi kilitle'),'lock','primary',errors.length||t().locked||active()||timeLeft()===0?'disabled':'')}${button('Stratejiye dön','go-studio','quiet')}</section></aside></div></main>`;}
function render(){document.documentElement.classList.toggle('reduce-motion',state.reduce);const views={studio,lobby,briefing,submit,moderator,stage,performance,final:finalPage};$('#app').innerHTML=shell((views[state.view]||studio)())+renderModal()+(countdown!==null?`<div class="countdown-overlay"><span>PAZAR AÇILIYOR</span><strong>${countdown}</strong>${button('Animasyonu atla','skip-countdown','secondary')}</div>`:'')+(state.finalReveal?`<div class="final-reveal"><div>${icon('cup',64)}<span>12 AY. 6 STRATEJİ.</span><h1>Kararlar verildi.<br>Şimdi sonuçlar konuşsun.</h1>${button('Sonuçları göster','skip-final','primary')}</div></div>`:'');bindDialog();}
function moderator(){const locked=state.teams.filter(x=>x.locked).length,disabled=active()?'disabled':'';return `<main class="page moderator-page">${pageHead('MODERATÖR / KONTROL ODASI','Oyunun ritmi sende.','Oturumu hazırla, teslimleri yönet ve ortak pazarı başlat.',`<span class="status-chip ${state.running?'success':''}">${state.phase==='complete'?'Tamamlandı':state.running?'Simülasyon sürüyor':active()?'Simülasyon durdu':'Kararlar bekleniyor'}</span>`)}<section class="control-deck"><div><small>TESLİM DURUMU</small><strong>${locked}<em>/ 6</em></strong><span>takımın stratejisi kilitli</span></div><div><small>GEÇEN SİMÜLASYON</small><strong>${state.month<0?'—':String(state.month+1).padStart(2,'0')}<em>/ 12</em></strong><span>${state.month<0?'Başlamaya hazır':MONTHS[state.month]}</span></div><div class="control-main">${!active()?button(icon('play',18)+' Simülasyonu başlat','start-sim','primary',locked<6?'disabled':''):button(icon(state.running?'pause':'play',18)+(state.running?' Duraklat':' Devam et'),'toggle-play','primary',state.month===11?'disabled':'')}<div>${button('Sonraki ay '+icon('chevron',16),'next-month','secondary',!active()||state.month===11?'disabled':'')}${button('Finali göster','show-final','secondary',state.month!==11?'disabled':'')}</div></div></section><div class="moderator-columns"><section class="white-panel"><div class="panel-heading"><h2>Takımlar</h2><span class="muted">Demo bağlantı durumu</span></div><div class="mod-team-list">${state.teams.map(x=>`<div>${emblem(x)}<span><strong>${esc(x.name)}</strong><small>${status(x)}</small></span>${!active()?button(x.locked?'Revizyon aç':'Varsayılanı uygula',x.locked?'revision':'default-team','quiet',`data-team-id="${x.id}"`):'<span class="status-chip">Kilitli</span>'}<button class="icon-btn" data-action="connection" data-team-id="${x.id}" title="Demo bağlantısını ${x.connected?'kes':'yeniden bağla'}" aria-label="${esc(x.name)} bağlantısını ${x.connected?'kes':'yeniden bağla'}">${icon(x.connected?'check':'reset',17)}</button></div>`).join('')}</div><div class="panel-actions">${button('Eksiklere varsayılanı uygula','defaults','secondary',disabled)}${button('Demo verisiyle prova','rehearse','quiet',disabled)}</div></section><section class="white-panel timing"><h2>Zaman ve gösterim</h2>${field('Karar süresi',`<div class="number-wrap"><input type="number" data-config="minutes" min="1" max="90" value="${state.config.minutes}" ${disabled}><span>dk</span></div>`)}${button('+5 dakika ekle','extend','secondary',disabled)}${field('Aylar arası bekleme',`<select data-config="speed">${[2,5,10,15].map(n=>`<option value="${n}" ${state.config.speed===n?'selected':''}>${n} saniye / ay</option>`).join('')}</select>`)}<label class="check-label"><input type="checkbox" data-setting="reduce" ${state.reduce?'checked':''}> Animasyonları azalt</label><label class="check-label"><input type="checkbox" data-setting="sound" ${state.sound?'checked':''}> Ay geçiş sesi</label>${button('Sahne ekranını aç '+icon('expand',16),'go-stage','quiet')}</section></div><details class="settings-section" ${!active()?'open':''}><summary><span>Senaryo ve puanlama</span><span>${active()?'Başlangıçta kilitlendi':'Düzenlenebilir demo varsayımları'}</span></summary><div class="settings-body"><div class="form-pair">${field('Senaryo yılı',`<input type="number" data-config="year" min="2000" max="2100" value="${state.config.year}" ${disabled}>`)}${field('Branş etiketi',`<input data-config="branch" maxlength="30" value="${esc(state.config.branch)}" ${disabled}>`,'Demo motoru kasko davranışını kullanır; diğer branşlar veri adaptörü gerektirir.')}</div><div class="mix-fields">${state.config.weights.map((w,i)=>field(['Kârlılık ağırlığı (%)','Pazar payı ağırlığı (%)','Deneyim ağırlığı (%)'][i],`<input type="number" data-weight="${i}" min="0" max="100" value="${w}" ${disabled}>`)).join('')}</div><p class="${state.config.weights.reduce((a,b)=>a+b,0)!==100?'error-text':'muted'}">Ağırlık toplamı: %${state.config.weights.reduce((a,b)=>a+b,0)} / %100</p><div class="assumption-grid">${Object.entries(state.config.assumptions).map(([k,v])=>field(v.label,`<div class="number-wrap"><input type="number" data-assumption="${k}" min="${v.min}" max="${v.max}" step="any" value="${v.value}" ${disabled}><span>${v.unit}</span></div>`,v.description)).join('')}</div></div></details><details class="settings-section"><summary><span>Olay takvimi</span><span>Yalnızca moderatör görünümü · demo</span></summary><div class="settings-body">${state.config.events.map((e,i)=>`<div class="event-editor">${field('Açıklanacağı ay',`<select data-event="${i}" data-prop="month" ${disabled}>${MONTHS.map((m,j)=>`<option value="${j}" ${j===e.month?'selected':''}>${m}</option>`).join('')}</select>`)}${field('Piyasa haberi',`<input data-event="${i}" data-prop="title" value="${esc(e.title)}" maxlength="80" ${disabled}>`)}${field('Hasar çarpanı',`<input type="number" data-event="${i}" data-prop="cost" min=".5" max="2" step=".01" value="${e.cost}" ${disabled}>`)}${field('Talep çarpanı',`<input type="number" data-event="${i}" data-prop="demand" min=".5" max="2" step=".01" value="${e.demand}" ${disabled}>`)}${field('Kanal çarpanı',`<input type="number" data-event="${i}" data-prop="channel" min=".5" max="2" step=".01" value="${e.channel}" ${disabled}>`)}</div>`).join('')}<p>Çarpanlar belirtilen aydan itibaren kalıcıdır. Tüm takımlara aynı ay uygulanır; etki portföye göre farklıdır.</p></div></details><div class="page-actions split">${button(icon('file',17)+' Oturumu dışa aktar','export','secondary')}<label class="btn secondary">Senaryo JSON yükle<input type="file" id="import-file" accept="application/json" hidden ${disabled}></label>${button(icon('reset',17)+' Yeni oturum','reset-session','quiet')}</div></main>`;}
function emptyStage(){return `<div class="race-empty"><div class="race-empty-mark">${icon('cup',54)}</div><div class="eyebrow">YARIŞ BAŞLAMAK ÜZERE</div><h2>Altı strateji.<br>Bir liderlik yarışı.</h2><p>Kararlar kilitlendiğinde moderatör simülasyonu başlatır.<br>Her ay, aynı pazarın yeni dengesi hesaplanır.</p><div class="starting-grid">${state.teams.map(x=>`<div>${emblem(x)}<span>${esc(x.name)}</span><small>${x.locked?'Hazır':'Karar veriyor'}</small></div>`).join('')}</div>${button('Kontrol odasına git '+icon('arrow',18),'go-moderator','primary')}</div>`;}
const metricLabel=()=>state.metric==='score'?'Geçici toplam puan':state.metric==='share'?'Prim bazlı pazar payı':'Teknik kâr';
const metricValue=(r,metric=state.metric)=>metric==='score'?fmt(r.score,1):metric==='share'?pct(r.share):money(r.profit);
function trend(teamId,metric='score'){if(state.month<0)return '';const values=state.results.slice(0,state.month+1).map(x=>x.rows.find(r=>r.id===teamId)[metric]);const max=Math.max(...values,metric==='score'?100:1),min=Math.min(0,...values),span=max-min||1;const points=values.map((v,i)=>`${18+i/11*404},${90-(v-min)/span*72}`).join(' ');return `<svg class="trend-chart" viewBox="0 0 440 112" role="img" aria-label="${esc(state.teams.find(t=>t.id===teamId).name)} aylık ${metricLabel()} trendi"><path d="M18 18H422 M18 54H422 M18 90H422" class="grid-line"/><polyline points="${points}" fill="none" stroke="${state.teams.find(x=>x.id===teamId).color}" stroke-width="3" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${18+i/11*404}" cy="${90-(v-min)/span*72}" r="${i===values.length-1?4:2}" fill="${state.teams.find(x=>x.id===teamId).color}"/>`).join('')}<text x="18" y="108">OCA</text><text x="400" y="108">ARA</text></svg>`;}
function raceRows(){const data=current();if(!data)return '';const rows=rank(data.rows,state.metric),previous=state.month>0?rank(state.results[state.month-1].rows,state.metric):null;const max=Math.max(...rows.map(x=>Math.abs(x[state.metric])),1);return `<div class="race-chart"><div class="race-axis"><span>TAKIM</span><span>${state.metric==='score'?'PUAN / 100':state.metric==='share'?'SİMÜLASYON PAZARI · %':'KÜMÜLATİF · TL'}</span><span>AYLIK SIRA</span></div><div class="race-lanes">${state.teams.map(team=>{const r=rows.find(x=>x.id===team.id),idx=rows.indexOf(r),prev=previous?.find(x=>x.id===r.id),delta=prev?prev.rank-r.rank:0;return `<button class="race-lane ${idx===0?'leader':''} ${!r.eligible?'ineligible':''}" data-focus-team="${team.id}" data-id="${team.id}" style="--team:${team.color};transform:translateY(${idx*66}px)"><span class="rank-number">${String(r.rank).padStart(2,'0')}</span>${emblem(team)}<span class="racer-name"><strong>${esc(team.name)}</strong><small>${!r.eligible?'Sermaye ihlali':team.code}</small></span><span class="race-bar-area"><span class="race-bar" style="width:${Math.max(2,Math.abs(r[state.metric])/max*100)}%"></span></span><strong class="racer-value">${metricValue(r)}</strong><span class="rank-delta ${delta>0?'up':delta<0?'down':''}">${delta>0?'↑ '+delta:delta<0?'↓ '+Math.abs(delta):'—'}</span>${idx===0&&state.metric==='score'?`<span class="leader-label">${icon('cup',12)} LİDER</span>`:''}</button>`;}).join('')}</div></div>`;}
function stage(){const d=current(),selected=state.teams.find(x=>x.id===state.focusTeam),lastEvent=state.results.slice(0,state.month+1).flatMap(x=>x.events).at(-1);return `<main class="stage-page"><div class="broadcast-header"><div><div class="broadcast-tag"><span class="live-dot"></span>${state.running?'CANLI SİMÜLASYON':state.month===11?'SEZON TAMAMLANDI':state.month>=0?'SİMÜLASYON DURDU':'YARIŞA HAZIR'}</div><h1>${state.config.year} <span>${esc(state.config.branch)} Arenası</span></h1></div><div class="broadcast-actions"><span class="demo-label">DEMO SENARYOSU</span><button class="icon-btn" data-action="fullscreen" aria-label="Tam ekran">${icon('expand',21)}</button></div></div><div class="timeline">${MONTHS.map((m,i)=>`<div class="${i===state.month?'active':i<state.month?'past':''}"><span>${m.slice(0,3).toLocaleUpperCase('tr-TR')}</span><i>${i<state.month?icon('check',11):''}</i></div>`).join('')}</div>${!d?emptyStage():`<div class="race-heading"><div><h2 id="race-title">${metricLabel()}</h2><span>Simülasyon pazarı <b>·</b> ${MONTHS[state.month]} ${state.config.year}</span></div><div class="metric-switch">${[['score','Toplam puan'],['share','Pazar payı'],['profit','Teknik kâr']].map(([v,l])=>`<button data-metric="${v}" class="${state.metric===v?'selected':''}">${l}</button>`).join('')}</div></div><div class="race-announcement ${leaderFlash?'visible':''}" aria-live="polite">${leaderFlash?`${icon('cup',18)} Yeni lider: ${esc(state.teams.find(x=>x.id===rank(d.rows)[0].id).name)}`:''}</div>${raceRows()}<div class="stage-support"><section class="news-panel"><div class="news-icon">${icon('bolt',26)}</div><div><small>PİYASA GÜNDEMİ · ${lastEvent?MONTHS[lastEvent.month].toLocaleUpperCase('tr-TR'):'OCAK'}</small><h3>${lastEvent?esc(lastEvent.title):'Pazar açıldı. İlk poliçeler yazılıyor.'}</h3><p>${lastEvent?esc(lastEvent.description):'Takımlar aynı müşteri havuzunda ilk paylarını almaya başladı.'}</p></div><span class="news-demo">DEMO OLAYI</span></section><section class="trend-panel"><div><span>${emblem(selected)}<strong>${esc(selected.name)}’ın yolculuğu</strong></span><small>${metricLabel()}</small></div>${trend(selected.id,state.metric)}</section></div>${state.detail?`<div class="stage-detail"><h3>${esc(selected.name)} — yayınlanmış sonuçlar</h3><div class="performance-stats">${stats(d.rows.find(x=>x.id===selected.id),true)}</div></div>`:''}<div class="stage-controls"><div>${button(icon(state.running?'pause':'play',17)+(state.running?' Duraklat':' Devam et'),'toggle-play','stage-btn',state.month===11?'disabled':'')}${button('Sonraki ay '+icon('chevron',16),'next-month','stage-btn',state.month===11?'disabled':'')}<select data-config="speed" aria-label="Gösterim hızı">${[2,5,10,15].map(n=>`<option value="${n}" ${state.config.speed===n?'selected':''}>${n} sn / ay</option>`).join('')}</select></div><span>${state.month+1} / 12 ay</span><div>${button(state.detail?'Detayı kapat':'Yayın detayını aç','toggle-detail','stage-btn')}${state.month===11?button('Finali göster '+icon('cup',17),'show-final','primary'):''}</div></div>`}</main>`;}
function stats(r,compact=false){return [['Poliçe adedi',fmt(r.policies)],['Brüt yazılan prim',money(r.gwp)],['Prim bazlı pazar payı',pct(r.share)],['Teknik kâr',money(r.profit)],...(!compact?[['Hasar oranı',pct(r.lossRatio)],['Bileşik oran',pct(r.combinedRatio)],['Hizmet sonucu',fmt(r.service,1)+' / 100'],['Adet bazlı pazar payı',pct(r.unitShare)]]:[])].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('');}
function performance(){const r=current()?.rows.find(x=>x.id===state.team);return `<main class="page">${pageHead('TAKIM PERFORMANSI',`${esc(t().name)}’ın karnesi.`,r?`${MONTHS[state.month]} ${state.config.year} · kümülatif sonuçlar · simülasyon pazarı`:'Sonuçların ilk ay tamamlandığında burada görünür.',teamSelect())}${!r?`<section class="empty-panel">${icon('chart',48)}<h2>Henüz poliçe üretilmedi.</h2><p>Stratejini teslim et; moderatör yılı başlattığında takımını buradan takip et.</p>${button('Karar teslimine git','go-submit','primary')}</section>`:`<div class="performance-stats">${stats(r)}</div><div class="brief-columns"><section class="white-panel"><h2>Bu ay neden değişti?</h2><ol class="explanation-list">${r.explanations.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section class="white-panel light-trend"><h2>Yıl içindeki yolculuğun</h2>${trend(t().id)}<div class="weight-line"><span>Geçici toplam puan</span><b>${fmt(r.score,1)} / 100</b></div><p>Sonuçlar gerçekleşen ortak pazar rekabetinden hesaplanır.</p></section></div><section class="white-panel"><h2>Teknik sonuç ve rezervler</h2><div class="finance-grid">${[['Net kazanılmış prim',r.netEarned],['Net gerçekleşen hasar',r.netClaims],['İlgili giderler',r.expenses],['Teknik kâr',r.profit],['Kazanılmamış net prim',r.upr],['Ödenmemiş net hasar',r.outstanding],['Nakit',r.cash],['Özkaynak',r.equity],['Devredilen prim',r.ceded],['Hasar geri kazanımı',r.recovery]].map(([k,v])=>`<div><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}</div><p class="muted">Nakit − kazanılmamış prim − ödenmemiş hasar = özkaynak. Rezervler teknik kârdan ikinci kez düşülmez.</p></section>`}</main>`;}
function debrief(team,r){return `<div class="debrief"><section><small>NE SEÇTİNİZ?</small><h3>${esc(team.strategy.sentence)}</h3><p>${team.strategy.price} fiyat endeksi, ${COVERAGES.find(x=>x.id===team.strategy.coverage).name.toLocaleLowerCase('tr-TR')}; ${money(team.strategy.marketing)} pazarlama ve ${money(team.strategy.service)} hizmet yatırımı.</p></section><section><small>NE OLDU?</small><h3>${pct(r.share)} pazar payı. ${money(r.profit)} teknik kâr.</h3><p>${fmt(r.policies)} poliçe, ${pct(r.combinedRatio)} bileşik oran ve ${fmt(r.service,1)}/100 hizmet sonucu elde ettiniz.</p></section><section><small>BELİRLEYİCİ ÖDÜNLEŞİM</small><h3>${r.combinedRatio>1?'Büyümenin maliyeti marjı aştı.':r.service<85?'Büyüme hizmet kapasitesini zorladı.':team.strategy.price<100?'Erişilebilir fiyat, daha dar birim marj.':'Fiyat disiplini ve portföy dengesi.'}</h3><p>${r.combinedRatio>1?`Her ₺100 kazanılmış net prime karşı ${money(r.combinedRatio*100)} hasar ve gider oluştu.`:r.service<85?`${fmt(r.policies)} poliçelik portföy, hizmet yatırımına göre kapasite baskısı oluşturdu.`:`${money(r.netEarned)} kazanılmış net primden ${money(r.netClaims)} hasar ve ${money(r.expenses)} gider karşılandı.`} Rakiplerin tercihleri de ulaştığınız hacmi etkiledi.</p></section></div>`;}
function finalPage(){if(state.month!==11)return `<main class="page">${pageHead('FİNAL & DEĞERLENDİRME','Şampiyonluk henüz açık.','Final sıralaması on iki ay tamamlandığında açıklanır.')}<section class="empty-panel">${icon('cup',56)}<h2>${Math.max(0,state.month+1)} / 12 ay tamamlandı.</h2><p>Yarışın gidişatını sahne ekranından takip edebilirsin.</p>${button('Yarışa dön '+icon('arrow',18),'go-stage','primary')}</section></main>`;const rows=rank(current().rows),podium=rows.filter(x=>x.eligible).slice(0,3),selected=state.teams.find(x=>x.id===state.focusTeam),r=rows.find(x=>x.id===selected.id);const first=rank(state.results[0].rows);const comeback=[...rows].sort((a,b)=>(first.find(x=>x.id===b.id).rank-b.rank)-(first.find(x=>x.id===a.id).rank-a.rank))[0];const badges=[['Pazar Lideri',[...rows].sort((a,b)=>b.share-a.share)[0]],['Kârlılık Ustası',[...rows].sort((a,b)=>b.profit-a.profit)[0]],['Müşteri Şampiyonu',[...rows].sort((a,b)=>b.service-a.service)[0]],['En Güçlü Geri Dönüş',comeback]];return `<main class="page final-page">${pageHead('SEZON FİNALİ / '+state.config.year,'Stratejiler yarıştı.<br>Sonuçlar konuşuyor.','12 ayın sonunda, ortak pazarın hesaplanan sonuçları.',button(icon('reset',17)+' Yarışı yeniden oynat','replay','secondary'))}<div class="podium">${[1,0,2].map(idx=>{const rr=podium[idx];if(!rr)return '';const team=state.teams.find(x=>x.id===rr.id);return `<div class="podium-team place-${idx+1}" style="--team:${team.color}"><span class="podium-caption">${idx===0?'ŞAMPİYON':idx===1?'İKİNCİ':'ÜÇÜNCÜ'}</span>${emblem(team,true)}<h2>${esc(team.name)}</h2><strong>${fmt(rr.score,1)}<small> / 100</small></strong><div class="podium-block">${rr.rank===1?icon('cup',38):String(rr.rank).padStart(2,'0')}</div></div>`;}).join('')||'<h2>Sermaye kuralını sağlayan takım bulunmuyor.</h2>'}</div><section class="white-panel"><div class="panel-heading"><h2>Altı strateji, tam sıralama</h2><span class="muted">Ayrıntılar için bir takım seç</span></div><div class="table-scroll"><table class="result-table"><thead><tr><th>Sıra / takım</th><th>Toplam puan</th><th>Teknik kâr</th><th>Prim payı</th><th>Deneyim</th><th>Durum</th></tr></thead><tbody>${rows.map(rr=>{const team=state.teams.find(x=>x.id===rr.id);return `<tr class="${rr.id===state.focusTeam?'selected':''}"><td><button data-focus-team="${team.id}"><b>${String(rr.rank).padStart(2,'0')}</b>${emblem(team)}${esc(team.name)}</button></td><td><strong>${fmt(rr.score,1)}</strong></td><td>${money(rr.profit)}</td><td>${pct(rr.share)}</td><td>${fmt(rr.service,1)}</td><td>${rr.eligible?'Uygun':'Sermaye ihlali'}</td></tr>`;}).join('')}</tbody></table></div></section><div class="badge-row">${badges.map(([l,rr])=>`<div>${icon('cup',21)}<span><small>${l}</small><strong>${l==='En Güçlü Geri Dönüş'&&first.find(x=>x.id===rr.id).rank-rr.rank<=0?'Sıra kazanan olmadı':esc(state.teams.find(x=>x.id===rr.id).name)}</strong></span></div>`).join('')}</div><section class="white-panel final-detail"><div class="panel-heading"><h2>${emblem(selected)} ${esc(selected.name)}: kararların karşılığı</h2><span>Modelden hesaplandı</span></div><div class="score-components">${r.components.map((v,i)=>`<div><span>${['Kârlılık','Pazar payı','Müşteri deneyimi'][i]} <b>%${state.config.weights[i]}</b></span><strong>${fmt(v,1)}<small>/ 100</small></strong><div class="component-track"><i style="width:${v}%"></i></div><p>Ham değer: ${[pct(r.profit/state.config.assumptions.capital.value)+' kâr / sermaye',pct(r.share)+' prim payı',fmt(r.service,1)+' hizmet skoru'][i]}</p><small>Toplama katkı: ${fmt(v*state.config.weights[i]/100,1)} puan</small></div>`).join('')}</div>${debrief(selected,r)}<details class="brief-rules"><summary>Seçilen strateji ve gerçekleşen dağılımlar</summary>${reviewTable(selected)}<div class="brief-columns"><div><h3>Gerçekleşen müşteri portföyü</h3>${r.segments.map((v,i)=>`<p>${SEGMENTS[i].name}: ${pct(v/r.policies||0)}</p>`).join('')}</div><div><h3>Gerçekleşen satış kanalları</h3>${r.channels.map((v,i)=>`<p>${['Direkt dijital','Acente','Broker'][i]}: ${pct(v/r.policies||0)}</p>`).join('')}</div></div></details></section><div class="page-actions">${button('Sonuçları dışa aktar','export','secondary')}</div></main>`;}
function renderModal(){if(!modal)return '';let content,title;if(modal==='brief'){title='Pazar dosyası';content=briefingContent();}else if(modal==='reset'){title='Yeni bir oturum başlat';content=`<p>Bu cihazdaki kararlar ve sonuçlar sıfırlanacak. Önce oturumu dışa aktararak saklayabilirsin.</p><div class="page-actions">${button('Oturumu dışa aktar','export')}${button('Yeni oturumu başlat','confirm-reset','primary')}</div>`;}else if(modal==='teams'){title='Demo takımını seç';content=`<p>Bu prototipte bütün takımlar aynı cihazda yönetilir. Gerçek kaptan yetkilendirmesi bulunmaz.</p><div class="demo-team-options">${state.teams.map(x=>`<button data-select-team="${x.id}">${emblem(x)}<span>${esc(x.name)}</span>${icon('arrow',18)}</button>`).join('')}</div>`;}else{title='Demo modeli ve bağlantı noktaları';content=`<p>Bu sürüm ${esc(state.config.version)} senaryosu ve ${state.config.seed} tohumu ile deterministiktir. Tarihsel 2023 verisi içermez.</p><h3>Hesaplama</h3><p>Segment başına ortak talep, altı şirketin göreli çekiciliği ve satın almama seçeneği arasında bölünür. Fiyat, kapsam, muafiyet, risk kabulü, bölge, pazarlama ve kanal karışımı talebi birlikte belirler.</p><p>Yıllık poliçe primi başlangıç ayı dahil ayda 1/12 kazanılır. Hasarlar gerçekleştiği ay giderleşir; ödenmeyen kısmı rezervdir. Komisyon yazılan prime, hasar kazanılmış risk maruziyetine bağlıdır. Kotpar reasürans net prim ve hasara bir kez yansır.</p><h3>Sınırlar</h3><p>Muafiyet, reasürans ve rezervler eğitim amaçlı basitleştirilmiştir. Hasar bazlı ödeme gelişimi, iptal, yatırım geliri ve vergi modellenmez. Sonuçlar gerçek sigorta fiyatlaması için kullanılamaz.</p><h3>Gerçek ürüne bağlantı</h3><p>Senaryo adaptörü tarihsel veriyi; simülasyon adaptörü aylık sonuç, olay, sıralama ve açıklamaları sağlar. Oturum servisi kaptan/moderatör yetkisini, takım verisi erişimini ve eşzamanlı durum yayınını sunucu tarafında uygulamalıdır. Bu demoda depolama yalnızca bu tarayıcıdadır.</p>`;}return `<dialog id="modal" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Pencereyi kapat">${icon('x')}</button></div><div class="modal-body">${content}</div></dialog>`;}
let returnFocus;function bindDialog(){const d=$('#modal');if(d&&!d.open){d.showModal();d.addEventListener('cancel',()=>{modal=null;});d.addEventListener('click',e=>{if(e.target===d){modal=null;render();}});}}
function updateLive(){if($('#live-summary'))$('#live-summary').innerHTML=summary();if($('#live-budget'))$('#live-budget').innerHTML=budget();if($('#price-reference'))$('#price-reference').innerHTML=`Referans: ${money(reference(s()))} / yıl → <strong>Teklifin: ${money(reference(s())*s().price/100)} / yıl</strong>`;for(const key of ['marketingMix','channels']){const el=$('#'+key+'-total'),total=s()[key].reduce((a,b)=>a+b,0);if(el){el.textContent=`Toplam %${fmt(total)} / %100 ${total===100?'✓':'· Dağılımı %100’e tamamlayın.'}`;el.classList.toggle('error-text',total!==100);}}}
function navigate(view){state.view=view;save();render();window.scrollTo(0,0);}
function applyDefault(id){const demo=teams().find(x=>x.id===id),target=state.teams.find(x=>x.id===id);target.strategy=demo.strategy;const budget=state.config.assumptions.budget.value,used=spend(target.strategy);if(used>budget){const ratio=budget/used;target.strategy.marketing=Math.floor(target.strategy.marketing*ratio);target.strategy.service=budget-target.strategy.marketing;}target.locked=true;target.revision=false;}
function beep(){if(!state.sound)return;try{const ctx=new AudioContext(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=440;g.gain.value=.035;o.start();g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.18);o.stop(ctx.currentTime+.2);o.onended=()=>ctx.close();}catch{}}
function schedule(){clearTimeout(timer);if(state.running&&state.month<11)timer=setTimeout(()=>advance(),state.config.speed*1000);}
function animateLanes(previousPositions){const lanes=document.querySelectorAll('.race-lane');if(!lanes.length||state.reduce||matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(const el of lanes){const old=previousPositions[el.dataset.id],end=el.style.transform;if(old&&old!==end)el.animate([{transform:old},{transform:end}],{duration:780,easing:'cubic-bezier(.2,.8,.2,1)'});}}
function advance(){if(!active()||state.month>=11)return;const prev={};document.querySelectorAll('.race-lane').forEach(el=>prev[el.dataset.id]=el.style.transform);const previousLeader=current()?.rows[0]?.id;state.month++;const newLeader=current()?.rows[0]?.id;leaderFlash=previousLeader!==undefined&&previousLeader!==newLeader;if(state.month===11){state.running=false;state.phase='complete';}save();render();animateLanes(prev);beep();if(leaderFlash)setTimeout(()=>{leaderFlash=false;$('.race-announcement')?.classList.remove('visible');},2800);schedule();}
function beginRun(){clearInterval(countdownTimer);countdown=null;state.phase='simulation';state.month=-1;state.running=true;state.view='stage';advance();}
function startSimulation(){if(active())return;const errs=state.teams.flatMap(team=>!team.locked?[`${team.name}: strateji teslim edilmedi.`]:validate(team,state.config));if(errs.length){toast(errs[0]);return;}try{state.results=simulate(state.teams,state.config);}catch(e){toast(e.message);return;}if(state.reduce||matchMedia('(prefers-reduced-motion: reduce)').matches){beginRun();return;}countdown=3;render();countdownTimer=setInterval(()=>{countdown--;if(countdown<=0)beginRun();else render();},850);}
function exportSession(){const payload={...state,exportedAt:new Date().toISOString()};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`risk-arenasi-${state.config.year}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Oturum ve sonuçlar dışa aktarıldı.');}
function checkedConfig(c){if(!c||typeof c!=='object')throw Error('Geçerli bir config alanı gerekli.');const base=scenario();for(const key of ['year','minutes','speed']){const ranges={year:[2000,2100],minutes:[1,90],speed:[2,15]},v=c[key];if(!Number.isFinite(v)||v<ranges[key][0]||v>ranges[key][1])throw Error(`${key} değeri geçersiz.`);base[key]=v;}if(typeof c.branch!=='string'||!c.branch.trim()||c.branch.length>30)throw Error('Branş etiketi geçersiz.');base.branch=c.branch;base.seed=Number.isInteger(c.seed)?c.seed:2023;if(!Array.isArray(c.weights)||c.weights.length!==3||c.weights.some(x=>!Number.isFinite(x)||x<0||x>100)||c.weights.reduce((a,b)=>a+b,0)!==100)throw Error('Ağırlıkların toplamı %100 olmalı.');base.weights=c.weights;for(const [key,def]of Object.entries(ASSUMPTIONS)){const v=c.assumptions?.[key]?.value;if(!Number.isFinite(v)||v<def.min||v>def.max)throw Error(`${def.label} geçersiz.`);base.assumptions[key].value=v;}if(!Array.isArray(c.events)||c.events.length>12)throw Error('Olay takvimi en fazla 12 olay içermeli.');base.events=c.events.map(e=>{if(!Number.isInteger(e.month)||e.month<0||e.month>11||typeof e.title!=='string'||!e.title.trim()||['cost','demand','channel'].some(k=>!Number.isFinite(e[k])||e[k]<.5||e[k]>2))throw Error('Olay ayı veya çarpanları geçersiz.');return{month:e.month,title:e.title.slice(0,80),description:typeof e.description==='string'?e.description.slice(0,240):e.title,cost:e.cost,demand:e.demand,channel:e.channel};});return base;}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field&&!t().locked&&!active()){const key=el.dataset.field;let v=el.type==='checkbox'?el.checked:el.type==='number'||el.type==='range'?Number(el.value):el.value;if(key==='name')t().name=v;else s()[key]=v;document.querySelectorAll(`[data-field="${key}"]`).forEach(other=>{if(other!==el)other.value=v;});save();updateLive();}if(el.dataset.mix&&!t().locked&&!active()){s()[el.dataset.mix][+el.dataset.index]=Number(el.value);save();updateLive();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.state==='team'){state.team=+el.value;save();render();}if(el.dataset.field&&el.tagName==='SELECT'&&!t().locked&&!active()){s()[el.dataset.field]=el.value;save();render();}if(el.dataset.config){if(active()&&el.dataset.config!=='speed')return;const k=el.dataset.config;if(el.type==='number'&&!el.checkValidity()){toast('Değeri izin verilen aralığa getirin.');render();return;}state.config[k]=k==='branch'?el.value:Number(el.value);if(k==='minutes')state.deadline=Date.now()+state.config.minutes*60000;save();schedule();render();}if(el.dataset.setting){state[el.dataset.setting]=el.checked;save();render();}if(el.dataset.weight!==undefined&&!active()){if(!el.checkValidity()){render();return;}state.config.weights[+el.dataset.weight]=Number(el.value);save();render();}if(el.dataset.assumption&&!active()){if(!el.checkValidity()){toast('Varsayımı izin verilen aralıkta girin.');render();return;}state.config.assumptions[el.dataset.assumption].value=Number(el.value);save();render();}if(el.dataset.event!==undefined&&!active()){if(!el.checkValidity()){toast('Olay değerini izin verilen aralıkta girin.');render();return;}state.config.events[+el.dataset.event][el.dataset.prop]=el.dataset.prop==='title'?el.value:Number(el.value);save();}if(el.id==='import-file'&&el.files[0]&&!active()){try{const file=el.files[0];if(file.size>200000)throw Error('Senaryo dosyası 200 KB sınırını aşıyor.');const data=JSON.parse(await file.text());state.config=checkedConfig(data.config||data);state.teams.forEach(x=>{x.locked=false;x.revision=true;});state.deadline=Date.now()+state.config.minutes*60000;save();render();toast('Senaryo yüklendi. Takımların kararlarını yeni kurallarla tekrar kilitleyin.');}catch(err){toast('Yüklenemedi: '+err.message);}}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,a[data-view]');if(!el||el.disabled)return;if(el.dataset.view){e.preventDefault();navigate(el.dataset.view);return;}if(el.dataset.step!==undefined){state.step=+el.dataset.step;save();render();return;}if(el.dataset.selectTeam!==undefined){state.team=+el.dataset.selectTeam;modal=null;navigate('studio');return;}if(el.dataset.focusTeam!==undefined){state.focusTeam=+el.dataset.focusTeam;save();render();return;}if(el.dataset.metric){const prev={};document.querySelectorAll('.race-lane').forEach(x=>prev[x.dataset.id]=x.style.transform);state.metric=el.dataset.metric;save();render();animateLanes(prev);return;}if(el.dataset.choice&&!t().locked&&!active()){const key=el.dataset.choice;s()[key]=['deductible','commission'].includes(key)?Number(el.dataset.value):el.dataset.value;save();render();return;}const a=el.dataset.action,id=Number(el.dataset.teamId);switch(a){case'next-step':if(state.step<3){state.step++;render();save();}else navigate('submit');break;case'prev-step':state.step--;render();save();break;case'go-studio':navigate('studio');break;case'go-submit':navigate('submit');break;case'go-stage':navigate('stage');break;case'go-moderator':navigate('moderator');break;case'start-brief':navigate('briefing');break;case'brief-modal':modal='brief';render();break;case'notes':modal='notes';render();break;case'team-picker':modal='teams';render();break;case'close-modal':modal=null;render();break;case'lock':if(!validate(t(),state.config).length&&!active()&&timeLeft()>0){t().locked=true;t().revision=false;save();render();toast('Stratejin kilitlendi. Yarışa hazırsın.');}break;case'revision':if(!active()){const team=state.teams.find(x=>x.id===id);team.locked=false;team.revision=true;save();render();toast(`${team.name} için revizyon açıldı.`);}break;case'default-team':if(!active()){applyDefault(id);save();render();}break;case'defaults':if(!active()){state.teams.filter(x=>!x.locked).forEach(x=>applyDefault(x.id));save();render();toast('Eksik takımlara brifingdeki demo stratejileri uygulandı.');}break;case'connection':state.teams.find(x=>x.id===id).connected=!state.teams.find(x=>x.id===id).connected;save();render();toast(state.teams.find(x=>x.id===id).connected?'Yeniden bağlandı · kararlar korundu.':'Demo bağlantısı kesildi · kararlar korundu.');break;case'extend':if(!active()){state.deadline=Math.max(Date.now(),state.deadline)+300000;save();render();toast('Karar süresine 5 dakika eklendi.');}break;case'start-sim':startSimulation();break;case'rehearse':if(!active()){state.teams.forEach(x=>{if(!x.locked)applyDefault(x.id);});startSimulation();}break;case'skip-countdown':beginRun();break;case'toggle-play':if(active()&&state.month<11){state.running=!state.running;save();render();schedule();}break;case'next-month':clearTimeout(timer);state.running=false;advance();break;case'toggle-detail':state.detail=!state.detail;save();render();break;case'show-final':if(state.month===11){state.view='final';state.finalReveal=!state.reduce&&!matchMedia('(prefers-reduced-motion: reduce)').matches;save();render();if(state.finalReveal)transitionTimer=setTimeout(()=>{state.finalReveal=false;render();},6500);}break;case'skip-final':clearTimeout(transitionTimer);state.finalReveal=false;render();break;case'replay':clearTimeout(timer);state.month=-1;state.phase='simulation';state.view='stage';state.running=true;advance();break;case'load-demo':if(active()){toast('Yeni demo için kontrol odasından yeni oturum başlat.');break;}state.teams=teams();state.teams.forEach(x=>applyDefault(x.id));state.deadline=Date.now()+state.config.minutes*60000;save();render();toast('Altı demo takım hazır. Kontrol odasından revizyon açarak değiştirebilirsin.');break;case'reset-session':modal='reset';render();break;case'confirm-reset':clearTimeout(timer);state=fresh();state.view='lobby';modal=null;save();render();break;case'export':exportSession();break;case'copy-code':try{await navigator.clipboard.writeText('RA-2023');toast('Oturum kodu kopyalandı: RA-2023');}catch{toast('Oturum kodu: RA-2023');}break;case'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.stage-page').requestFullscreen();}catch{toast('Tarayıcının tam ekran komutunu kullanabilirsin.');}break;}});
setInterval(()=>{const el=$('#countdown-clock');if(el&&!active()){el.textContent=clockText();el.closest('.timer')?.classList.toggle('time-warning',timeLeft()<120);}if(timeLeft()===0&&!active()){const lock=$('[data-action="lock"]');if(lock)lock.disabled=true;}},1000);
window.addEventListener('online',()=>{toast('Yeniden bağlandı. Yerel oturum korundu.');render();});window.addEventListener('offline',()=>{toast('Bağlantı kesildi. Bu cihazdaki oyun çalışmaya devam eder.');render();});
render();save();

// The same core workshop actions are exposed to supporting browser agents when
// the experimental WebMCP surface is available. The visible UI remains the
// source of truth and is re-rendered after every successful action.
function registerModelTools(){
  const context=document.modelContext;
  if(!context?.registerTool)return;
  const register=tool=>Promise.resolve(context.registerTool(tool)).catch(()=>{});
  register({
    name:'read_workshop_state',
    title:'Workshop durumunu oku',
    description:'Seçili takım, oyun aşaması, ay ve teslim durumlarını okur.',
    inputSchema:{type:'object',properties:{},additionalProperties:false},
    annotations:{readOnlyHint:true,untrustedContentHint:false},
    execute(){return{phase:state.phase,month:state.month<0?null:MONTHS[state.month],selectedTeam:t().name,teams:state.teams.map(team=>({name:team.name,status:status(team)}))};}
  });
  register({
    name:'configure_selected_team',
    title:'Seçili takım stratejisini ayarla',
    description:'Seçili ve kilitlenmemiş takımın fiyat, kapsam, pazarlama ve hizmet kararlarını tek işlemde günceller.',
    inputSchema:{type:'object',properties:{price:{type:'number',minimum:80,maximum:120},coverage:{type:'string',enum:['narrow','balanced','wide']},marketing:{type:'number',minimum:0},service:{type:'number',minimum:0}},additionalProperties:false},
    annotations:{readOnlyHint:false,untrustedContentHint:false},
    execute(input){
      if(active())throw Error('Simülasyon başladı; stratejiler değiştirilemez.');
      if(t().locked)throw Error('Seçili takım kilitli; moderatör revizyon açmalı.');
      const candidate={...s(),...input};
      if(!Number.isFinite(candidate.price)||candidate.price<80||candidate.price>120)throw Error('Fiyat endeksi 80–120 aralığında olmalı.');
      if(!COVERAGES.some(x=>x.id===candidate.coverage))throw Error('Teminat dar, dengeli veya geniş olmalı.');
      if(!Number.isFinite(candidate.marketing)||!Number.isFinite(candidate.service)||candidate.marketing<0||candidate.service<0)throw Error('Bütçeler sıfır veya pozitif olmalı.');
      if(candidate.marketing+candidate.service>state.config.assumptions.budget.value)throw Error('Pazarlama ve hizmet yatırımı karar bütçesini aşıyor.');
      Object.assign(s(),candidate);save();render();
      return{team:t().name,price:s().price,coverage:s().coverage,marketing:s().marketing,service:s().service,remainingBudget:state.config.assumptions.budget.value-spend(s())};
    }
  });
  register({
    name:'prepare_demo_race',
    title:'Demo yarışını hazırla',
    description:'Altı örnek takımı varsayılan stratejileriyle doldurur ve geçerli kararları kilitler.',
    inputSchema:{type:'object',properties:{},additionalProperties:false},
    annotations:{readOnlyHint:false,untrustedContentHint:false},
    execute(){
      if(active())throw Error('Devam eden simülasyon sırasında demo takımları yeniden hazırlanamaz.');
      state.teams=teams();state.teams.forEach(team=>applyDefault(team.id));state.deadline=Date.now()+state.config.minutes*60000;save();render();
      return{readyTeams:state.teams.filter(team=>team.locked).length,totalTeams:state.teams.length};
    }
  });
}
registerModelTools();

function strategyArchetype(st){
  if(st.price<=94&&st.marketing>=2500000)return'Hacim avcısı';
  if(st.risk==='selective'&&st.price>=106)return'Seçici marj';
  if(st.coverage==='wide'&&st.service>=2000000)return'Premium güvence';
  if(st.channels[0]>=60)return'Dijital hücum';
  if(st.channels[1]>=55)return'Acente gücü';
  return'Dengeli operatör';
}
function strategySignals(st){
  const limit=state.config.assumptions.budget.value||1;
  const bound=value=>Math.max(8,Math.min(100,Math.round(value)));
  return[
    {label:'Büyüme baskısı',value:bound(48+(100-st.price)*1.4+st.marketing/limit*30+(st.risk==='broad'?14:st.risk==='selective'?-12:0))},
    {label:'Marj disiplini',value:bound(48+(st.price-100)*1.7+st.deductible/10000*12+(st.risk==='selective'?17:st.risk==='broad'?-14:0)+(st.coverage==='narrow'?10:st.coverage==='wide'?-11:0))},
    {label:'Hizmet hazırlığı',value:bound(18+st.service/limit*82)}
  ];
}
function decorateGameSurface(){
  const studioPage=document.querySelector('.studio-page');
  if(!studioPage)return;
  let hud=studioPage.querySelector('.arena-hud');
  if(!hud){hud=document.createElement('section');hud.className='arena-hud';studioPage.querySelector('.team-context')?.insertAdjacentElement('afterend',hud);}
  const labels=['Ürün tasarımı','Pazar pozisyonu','Büyüme planı','Operasyon gücü'];
  const signals=strategySignals(s());
  hud.style.setProperty('--team',t().color);
  studioPage.style.setProperty('--team',t().color);
  hud.innerHTML=`<div class="arena-identity"><span class="arena-command">TAKIM TAKTİK EKRANI</span><div>${emblem(t(),true)}<span><small>STRATEJİ SINIFI</small><strong>${strategyArchetype(s())}</strong></span></div></div><div class="strategy-radar"><div class="radar-heading"><span>Karar yönü</span><small>Nitel gösterge · sonuç tahmini değildir</small></div>${signals.map(signal=>`<div class="radar-line"><span>${signal.label}</span><div><i style="width:${signal.value}%"></i></div><b>${signal.value<38?'Temkinli':signal.value>68?'Güçlü':'Dengeli'}</b></div>`).join('')}</div><div class="round-card"><small>KARAR TURU</small><strong>${String(state.step+1).padStart(2,'0')}<em>/04</em></strong><span>${labels[state.step]}</span><i>${t().locked?'KİLİTLİ':'KAPTAN KARARI'}</i></div>`;
}
document.addEventListener('input',()=>queueMicrotask(decorateGameSurface));
document.addEventListener('change',()=>queueMicrotask(decorateGameSurface));
document.addEventListener('click',()=>queueMicrotask(decorateGameSurface));
decorateGameSurface();
